#include <bits/stdc++.h>
using namespace std;

long long n, a[200005];
char c[200005];

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i] >> c[i];

    // 从两端往中间合并：x、y 是当前左右两段还剩多少个字符
    long long l = 1, r = n, ans = 0, x = a[l], y = a[r];
    while (l < r) {
        long long minn = min(x, y);      // 这一次能对齐 minn 对
        if (c[l] != c[r]) ans += minn;   // 字符不同，这 minn 对每对都要改一个
        x -= minn;
        y -= minn;
        if (x == 0) { l++; x = a[l]; }   // 左边这段用完，换下一段
        if (y == 0) { r--; y = a[r]; }   // 右边同理
    }
    cout << ans;
    return 0;
}
